/*
 * The backend, at <origin>/mt, typed from MicroTeams-API.yml (schema.d.ts is generated by
 * `npm run codegen` and not committed).
 *
 * createMtClient({origin, token, reauthorize, fetch}) → an openapi-fetch client whose every call
 *   carries the current bearer token, and which, on a 401, asks reauthorize() for a new one once and
 *   retries. A call the server refused throws MtError with the server's own message.
 * MtError — what the backend refused, with its own message and the HTTP status.
 * MtClient — the type of what createMtClient returns.
 * Schema — the generated component types, e.g. Schema["Message"].
 *
 * Example:
 *   const mt = createMtClient({ origin, token: () => session.accessToken, reauthorize });
 *   const { data } = await mt.GET("/chat", { params: { query: { page_size: 50 } } });
 */
import createClient, { type Middleware } from "openapi-fetch";
import type { components, paths } from "./schema";

export type Schema = components["schemas"];

export class MtError extends Error {
  constructor(
    message: string,
    readonly status: number,
  ) {
    super(message);
  }
}

/** Nothing for a success; otherwise the server's own message, thrown. */
async function failIfRefused(response: Response): Promise<void> {
  if (response.ok) return;
  let message = `HTTP ${response.status}`;
  try {
    const body = (await response.clone().json()) as { message?: string };
    if (body.message) message = body.message;
  } catch {
    // A body that is not JSON keeps the status as the message.
  }
  throw new MtError(message, response.status);
}

export function createMtClient(opts: {
  origin: string;
  token: () => string | null;
  /** A fresh token after a 401, or null when the session is over. */
  reauthorize: () => Promise<string | null>;
  fetch?: typeof fetch;
}) {
  const plainFetch = opts.fetch ?? globalThis.fetch;
  const client = createClient<paths>({ baseUrl: `${opts.origin}/mt`, fetch: plainFetch });
  // An untouched copy of each request, because the one that was sent has had its body read and a
  // retry of a POST needs the body again.
  const unsent = new WeakMap<Request, Request>();

  const auth: Middleware = {
    onRequest({ request }) {
      const token = opts.token();
      if (token) request.headers.set("Authorization", `Bearer ${token}`);
      unsent.set(request, request.clone());
      return request;
    },
    async onResponse({ request, response }) {
      if (response.status === 401 && !request.headers.has("X-MT-Retried")) {
        const fresh = await opts.reauthorize();
        if (fresh) {
          const again = unsent.get(request) ?? request;
          again.headers.set("Authorization", `Bearer ${fresh}`);
          again.headers.set("X-MT-Retried", "1");
          const retried = await plainFetch(again);
          await failIfRefused(retried);
          // openapi-fetch takes a replacement only as this runtime's own Response; React Native's
          // fetch may hand back another implementation of it.
          return retried instanceof Response
            ? retried
            : new Response(await retried.arrayBuffer(), { status: retried.status, headers: retried.headers });
        }
      }
      // Returning nothing keeps the response as it is.
      await failIfRefused(response);
      return undefined;
    },
  };
  client.use(auth);
  return client;
}

export type MtClient = ReturnType<typeof createMtClient>;
